contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address _to, uint256 _value) public {
        require(_to != address(0));
        uint256 senderBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 toBefore = c.balanceOf(_to); if (__ESBMC_reverted()) return;
        uint256 totalBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        require(senderBefore >= _value);
        require(toBefore + _value >= toBefore);
        require(_to != address(this));
        bool success = c.transfer(_to, _value); if (__ESBMC_reverted()) return;
        uint256 senderAfter = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 toAfter = c.balanceOf(_to); if (__ESBMC_reverted()) return;
        uint256 totalAfter = c.totalSupply(); if (__ESBMC_reverted()) return;
        assert(success == true && senderBefore - senderAfter == _value && toAfter - toBefore == _value && totalAfter == totalBefore);
    }

    receive() external payable {}
}

